<?php
namespace App\Http\Controllers; use App\Models\Holiday; use App\Services\NationalHolidayService; use Illuminate\Http\Request; use Throwable;
class HolidayController extends Controller { public function index(Request $r){$year=(int)($r->year?:now()->year);return view('holidays.index',['year'=>$year,'holidays'=>Holiday::whereYear('holiday_date',$year)->orderBy('holiday_date')->get()]);} public function store(Request $r){$data=$r->validate(['holiday_date'=>'required|date','name'=>'required|string|max:150','notes'=>'nullable|string|max:500']);Holiday::updateOrCreate(['holiday_date'=>$data['holiday_date']],$data);return back()->with('success','Hari libur berhasil disimpan.');} public function sync(Request $r,NationalHolidayService $service){$year=(int)$r->input('year',now()->year);try{$count=$service->sync($year);return back()->with('success',"{$count} hari libur nasional {$year} berhasil disinkronkan.");}catch(Throwable $e){return back()->withErrors(['calendar'=>'Sinkronisasi gagal. Periksa koneksi internet lalu coba lagi.']);}} public function destroy(Holiday $holiday){$holiday->delete();return back()->with('success','Hari libur dihapus.');} }
